import "core-js/modules/web.dom.iterable";
import { getRacksDetail, addRacks, getDeviceList } from "@/api/device/resoureracks";
import { getDictList as _getDictList } from "@/api/dict";
import xtTreeLzaySelect from "@/components/xtTreeLzaySelect/index.vue";
import { getDeptList as _getDeptList } from "@/api/system/dept";
export default {
  props: ["racksId"],
  components: {
    xtTreeLzaySelect: xtTreeLzaySelect
  },
  data: function data() {
    return {
      runningStatusList: [],
      racksOccupancyList: [],
      maintenanceFactoryList: [],
      searchForm: {
        current: 1,
        size: 20
      },
      racksDetail: {},
      rules: {
        racksName: [{
          required: true,
          message: '名称不能为空',
          trigger: 'blur'
        }],
        belongRacks: [{
          required: true,
          message: '所属机柜不能为空',
          trigger: 'blur'
        }],
        useDate: [{
          required: true,
          message: '投运日期不能为空',
          trigger: 'blur'
        }],
        racksOccupancy: [{
          required: true,
          message: '机架占用不能为空',
          trigger: 'blur'
        }],
        racksNum: [{
          required: true,
          message: '机架序号不能为空',
          trigger: 'blur'
        }]
      },
      isSave: false,
      saveLoading: false,
      tableHeight: undefined,
      tableLoading: false,
      total: 0,
      activeName: '0',
      tableData: [],
      unitList: []
    };
  },
  watch: {
    racksId: function racksId() {
      this.getList();
      this.getDetail();
    }
  },
  mounted: function mounted() {
    var _this = this;
    //获取 部门列表
    this.getDeptList();
    //字典加载
    this.getDictList("maintenanceFactory");
    this.getDictList("yesNo");
    this.getDictList("cabinets_status");
    this.$nextTick(function () {
      _this.setTableHeight();
    });
    this.getDetail();
    this.getList();
  },
  methods: {
    getDeptList: function getDeptList() {
      var _this2 = this;
      //获取部门 单位
      _getDeptList().then(function (res) {
        _this2.unitList = res.data;
      });
    },
    getEntityUnit: function getEntityUnit(val) {
      //选择领用单位 部门
      this.racksDetail.maintenanceUnit = val.fullName;
      this.$refs.racksDetail.$forceUpdate();
      this.$forceUpdate();
    },
    getDictList: function getDictList(code) {
      var _this3 = this;
      _getDictList(code).then(function (res) {
        if (code === "maintenanceFactory") {
          _this3.maintenanceFactoryList = res.data;
        } else if (code === "yesNo") {
          _this3.racksOccupancyList = res.data;
        } else if (code === "cabinets_status") {
          _this3.runningStatusList = res.data;
        }
      });
    },
    saveDetailBtn: function saveDetailBtn() {
      var _this4 = this;
      this.$refs.racksDetail.validate(function (valid) {
        if (valid) {
          _this4.saveLoading = true;
          addRacks(_this4.racksDetail).then(function () {
            _this4.$message({
              type: "success",
              message: "操作成功!"
            });
            _this4.racksDetail.title = _this4.racksDetail.racksName;
            _this4.isSave = false;
            _this4.$emit('updateNode', {
              handleType: '修改',
              dataType: 'racks',
              nodeDetail: _this4.racksDetail
            });
            _this4.saveLoading = false;
            _this4.getDetail();
          });
        }
      });
    },
    setTableHeight: function setTableHeight() {
      var pageBody = document.getElementsByClassName('page_body');
      this.tableHeight = pageBody[0].offsetHeight - 55 - 48 - 47 + 'px';
    },
    getDetail: function getDetail() {
      var _this5 = this;
      getRacksDetail(this.racksId).then(function (res) {
        _this5.racksDetail = res.data;
      });
    },
    getList: function getList() {
      var _this6 = this;
      this.tableLoading = true;
      this.searchForm.rackCode = this.racksId;
      getDeviceList(this.searchForm).then(function (res) {
        _this6.tableData = res.data.data;
        _this6.tableLoading = false;
        _this6.tableData.forEach(function (item) {
          // if()
          item.rackUse = item.deviceHeightEnd - item.deviceHeightBegin + 1;
        });
      });
    },
    search: function search() {
      this.searchForm.current = 1;
      this.getList();
    },
    restForm: function restForm() {
      this.searchForm = {
        current: 1,
        size: 20
      };
      this.getList();
    },
    changeReturnDate: function changeReturnDate(val) {
      if (val != null) {
        if (new Date(val).getTime() < new Date(this.cabinetsDetail.useDate).getTime()) {
          this.$message({
            type: "warning",
            message: "退运日期不可小于投运日期!"
          });
          this.cabinetsDetail.returnDate = null;
        }
      }
    }
  }
};
